#!/usr/bin/env bash
set -euo pipefail

# Run from the intended repository checkout after the client dependency batch.
# Package edits are generated by the SDK; do not copy older project files over it.
cd "$(git rev-parse --show-toplevel)"
python3 - <<'PY'
from pathlib import Path
import xml.etree.ElementTree as ET

def packages(project):
    return {item.attrib['Include']: item.attrib.get('Version')
            for item in ET.parse(Path('src') / project / (project + '.csproj')).iter('PackageReference')}

api = packages('Helpdesk.API')
infrastructure = packages('Helpdesk.Infrastructure')
shared = packages('Helpdesk.Shared')
defaults = packages('Helpdesk.ServiceDefaults')
assert api.get('Npgsql') == '10.0.3', 'Apply the generated client dependency batch first.'
assert infrastructure.get('Npgsql') == '10.0.3', 'Apply the generated client dependency batch first.'
assert 'Npgsql' not in shared, 'Shared still owns the driver; host reduction would be incomplete.'
assert defaults.get('Npgsql.OpenTelemetry') == '10.0.3', 'Review the instrumentation version before moving it.'
assert 'Npgsql.OpenTelemetry' not in api, 'The package move has already been applied or the source changed.'
PY

dotnet --version
dotnet add src/Helpdesk.API/Helpdesk.API.csproj package Npgsql.OpenTelemetry --version 10.0.3 --no-restore
dotnet remove src/Helpdesk.ServiceDefaults/Helpdesk.ServiceDefaults.csproj package Npgsql.OpenTelemetry
git diff --check
